const d = $input.first().json;
const instruction = `Return ONLY strict JSON. No markdown fences. Required top-level shape: {"sections":[{"id":"...","prose":"...","factsCited":["..."]}]}. Every prose paragraph must be traceable to factsCited. Do not copy or alter the verified facts.`;
const payload = {birthData:d.birthData, verifiedFacts:d.verifiedFacts, reportType:d.reportType, tier:d.tier};
return [{json:{...d, aiPrompt:`${d.pipelineConfig.prompt}

${instruction}

AUTHORITATIVE INPUT JSON:
${JSON.stringify(payload)}`}}];

const d = $('Build Writer Prompt').first().json;
const raw = $input.first().json.text ?? $input.first().json.output ?? $input.first().json.content ?? '';
function parse(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value).trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
  try { return JSON.parse(text); } catch (_) {}
  try { return JSON.parse(require('jsonrepair').jsonrepair(text)); } catch (_) {}
  const a = text.indexOf('{'), b = text.lastIndexOf('}');
  if (a >= 0 && b > a) {
    const candidate = text.slice(a,b+1);
    try { return JSON.parse(candidate); } catch (_) { return JSON.parse(require('jsonrepair').jsonrepair(candidate)); }
  }
  throw new Error('Writer returned non-JSON output');
}
const parsed = parse(raw);
if (!Array.isArray(parsed.sections) || !parsed.sections.length) throw new Error('Writer returned no sections');
return [{json:{...d, generated:parsed, rawWriterOutput:undefined}}];

const d = $input.first().json;
const sections = d.generated?.sections || [];
const banned = ["with time and effort", "navigate life's challenges with greater ease", "navigate the complexities of life", "the universe is calling upon you", "the universe is always guiding you", "a journey of self-discovery", "embark on this journey", "embark on a journey", "embrace the challenges and opportunities", "you possess the inner wisdom", "as we embark", "as we weave together", "a tapestry of energies", "deepen your connection with your emotions", "trust in the process", "soulmate", "soulmates", "twin flame", "destined to be together", "meant to be together", "guaranteed", "guarantee", "you will marry", "you will meet the one", "they will come back", "break up", "you should leave", "you should stay", "is he cheating", "is she cheating", "catch them", "lying to you", "this will happen", "this is your fate", "doomed", "cursed", "ruined by", "guaranteed love", "guaranteed success", "guaranteed money"];
const tonePatterns = ["will definitely", "will certainly", "must leave", "must stay", "diagnosed with", "legal advice", "medical advice", "saturn will destroy", "mercury retrograde will ruin"];
const required = d.pipelineConfig.required || [];
const prefixes = d.pipelineConfig.prefixes || [];
const issues = [];
const factBlob = JSON.stringify(d.verifiedFacts).toLowerCase();
const ids = sections.map(s => String(s.id || ''));
for (const id of required) if (!ids.includes(id)) issues.push(`structure: missing ${id}`);
for (const prefix of prefixes) if (!ids.some(id => id.startsWith(prefix))) issues.push(`structure: missing ${prefix}*`);
const normalize = s => String(s || '').toLowerCase().replace(/[^a-z0-9.]+/g,' ').trim();
const shingles = s => { const w=normalize(s).split(/\s+/).filter(Boolean); const out=new Set(); for(let i=0;i<=w.length-5;i++) out.add(w.slice(i,i+5).join(' ')); return out; };
const paraRows = [];
for (const section of sections) {
  if (!section.id || typeof section.prose !== 'string' || !section.prose.trim()) { issues.push(`structure: malformed section ${section.id || 'unknown'}`); continue; }
  if (!Array.isArray(section.factsCited) || !section.factsCited.length) issues.push(`specificity: no factsCited in ${section.id}`);
  const proseLower = section.prose.toLowerCase();
  for (const phrase of banned) if (proseLower.includes(phrase)) issues.push(`bannedPhrase: '${phrase}' in ${section.id}`);
  for (const phrase of tonePatterns) if (proseLower.includes(phrase)) issues.push(`tone: '${phrase}' in ${section.id}`);
  if (section.prose.includes('—')) issues.push(`style: em-dash in ${section.id}`);
  const paragraphs = section.prose.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);
  if ((section.factsCited || []).length < paragraphs.length) issues.push(`specificity: fewer citations than paragraphs in ${section.id}`);
  for (const citation of (section.factsCited || [])) {
    const nums = String(citation).match(/\d+(?:\.\d+)?/g) || [];
    if (nums.some(n => !factBlob.includes(n))) issues.push(`factual: citation not found in verifiedFacts: ${citation}`);
  }
  for (const p of paragraphs) paraRows.push({id:section.id,text:p,set:shingles(p)});
}
for (let i=0;i<paraRows.length;i++) for(let j=i+1;j<paraRows.length;j++) {
  const a=paraRows[i].set,b=paraRows[j].set; if(!a.size||!b.size) continue;
  let overlap=0; for(const x of a) if(b.has(x)) overlap++;
  const ratio=overlap/Math.min(a.size,b.size);
  if(ratio>0.30) issues.push(`duplicate: ${paraRows[i].id} vs ${paraRows[j].id} (${Math.round(ratio*100)}%)`);
}
return [{json:{...d, lint:{attempt:1, passed:issues.length===0, issues}}}];

const d=$input.first().json;
const aiPrompt=`Revise the JSON report below once. Fix every listed deterministic lint issue without inventing facts. Return ONLY the complete strict JSON object {"sections":[...]}.

ISSUES:
${d.lint.issues.join('\\n')}

AUTHORITATIVE FACTS:
${JSON.stringify(d.verifiedFacts)}

CURRENT REPORT:
${JSON.stringify(d.generated)}`;
return [{json:{...d,attempt:2,aiPrompt}}];

