const d=$input.first().json;
const rubric={hardGates:['factual','banned','specific','dup','tone','structure','length','ageConsent'],scores:['precision','insightDensity','voiceFit','empowerment','personalization','clarity','cohesion']};
const aiPrompt=`Judge this report against the supplied CSG quality bar. Return ONLY strict JSON: {"hardGates":{"factual":true,"banned":true,"specific":true,"dup":true,"tone":true,"structure":true,"length":true,"ageConsent":true},"scores":{"precision":1,"insightDensity":1,"voiceFit":1,"empowerment":1,"personalization":1,"clarity":1,"cohesion":1},"verdict":"pass|revise|reject","flags":[],"notes":"..."}. Paid requires every score >=4. Free requires every score >=3. Deterministic lint already passed; do not override a factual problem you detect.

RUBRIC:${JSON.stringify(rubric)}
FACTS:${JSON.stringify(d.verifiedFacts)}
REPORT:${JSON.stringify(d.generated)}`;
