const d=$('Build Judge Prompt').first().json;
const raw=$input.first().json.text ?? $input.first().json.output ?? $input.first().json.content ?? '';
const text=String(raw).trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
let judge;try{judge=JSON.parse(text);}catch(_){const a=text.indexOf('{'),b=text.lastIndexOf('}');const candidate=a<0||b<=a?text:text.slice(a,b+1);judge=JSON.parse(require('jsonrepair').jsonrepair(candidate));}
const gates=Object.values(judge.hardGates||{});const scores=Object.values(judge.scores||{}).map(Number);
const threshold=d.tier==='paid'?4:3;
const passed=judge.verdict==='pass'&&gates.length>=8&&gates.every(Boolean)&&scores.length>=7&&scores.every(x=>x>=threshold);
const status=passed?(d.tier==='paid'?'needs_editor':'approved'):'rejected';
const reasons=passed?[]:[...(judge.flags||[]),...(judge.notes?[judge.notes]:[])];
return [{json:{reportId:d.reportId,reportType:d.reportType,tier:d.tier,callbackUrl:d.callbackUrl,dispatchClaim:d.dispatchClaim,status,sections:d.generated.sections,judge,editorNote:d.tier==='paid'&&passed?'Human editor sign-off required before approved delivery':null,rejectReasons:reasons}}];
